var OPN=["{w} is waiting at {s} with a worn envelope.","At {s}, the stamp bleeds ink and reveals a hidden line.","{w} calls it luck, but {s} was never an accident on Marlowe's route.","In {s}, someone has left the envelope exactly where only you would look.","{w} meets you in {s} and speaks slowly, so you can take it in at your own pace.","The post office in {s} is closed, yet one envelope is waiting for you.","At {s}, {w} hands you something wrapped in brown paper.","{s} hums with a quiet you can almost hear. {w} nods at the envelope.","{w} spreads the day's map across a bench in {s}.","You arrive in {s} and the stamp feels warm, as if it remembers something."];
var EVD=["Inside: {m}.","Wrapped in the letter: {m}.","Tucked behind the stamp: {m}.","On the back of the card: {m}.","Taped inside the flap: {m}.","Pressed between two pages: {m}.","Slipped into the lining: {m}.","The envelope also holds {m}."];
var HK=["Marlowe's margin note: 'Not hidden. Waiting for someone who notices.'","The Hush has been here: one line has been scrubbed grey.","{w} frowns. 'The missing part is the part she loved most.'","A second hand has added: 'Try harder to be like everyone else.' It is not hers.","You add the clue to your casebook. Your way of noticing is the point.","'You do not have to see it all at once,' says {w}. 'Follow what pulls you.'","The ink spells a number: the next stop is closer than it looks.","Marlowe wrote: 'Different minds, same sky.'","The back reads: 'Say one true thing to one person today.'","'She was right about you,' {w} says quietly."];
var MOT=[["a pressed violet","a train ticket stamped 6:07","a tide table with one date circled","a wax seal shaped like a compass","a recipe card in Marlowe's handwriting","a key that fits no door"],["a brass bell with no clapper","a page torn from a language primer","a photograph with one face scratched out","a coin from a country that no longer exists","a folded paper crane","a radio schedule with a station underlined"],["a glass bead the colour of dusk","a thread from a prayer rug","a handwritten map of a market","a cassette labelled 'loud days'","a spice-stained note about sensory quiet","a tiny brass telescope"],["a drum skin patched with blue cloth","a seed packet from a garden Marlowe never planted","a letter in three languages","a single kora string","a weather chart with a storm circled","a carved wooden comb"],["a paper lantern","a train timetable written in pencil","a jade button","an abacus missing one bead","a hand fan with a hidden line of text","a pocket map of a night market"],["a shell worn smooth by water","a navigation chart drawn in chalk","a corner of a woven mat","a sealed bottle","a compass that points to people instead of north","a lighthouse log with torn pages"],["a ticket for a train that never left","a bundle of unsent letters","a bookmark printed with jaguar spots","a mirror painted over with grey","the first letter, still unopened","a key that finally fits"]];
var SPK=[[1,0],[2,1],[3,2],[6,3],[4,7],[4,0],[7,6]];
var SIG=["Autism and ADHD often occur together. Many people find out as adults.","Masking, hiding your natural ways to fit in, is exhausting. Safe spaces make unmasking possible.","Many people with AuDHD describe wanting routine and novelty at the same time. Both are real.","Motivation often follows interest rather than importance. That is not laziness.","Clear, literal communication helps everyone. Say what you mean and what you need.","Sensory differences vary. Noise, light and texture can be painful or deeply enjoyable.","Strengths often include deep focus, pattern spotting, honesty and creativity.","Rest is not a reward you earn. Everyone needs recovery, especially after masking.","Support looks different for everyone. Ask, do not assume.","Being different is not being broken. Acceptance changes lives."];
var RID=[["I speak without a mouth and hear without ears. What am I?","An echo."],["The more you take, the more you leave behind. What am I?","Footsteps."],["What has cities but no houses, mountains but no trees, and water but no fish?","A map."],["What can travel the world while staying in a corner?","A stamp."],["I have keys but no locks, and space but no room. What am I?","A keyboard."],["What gets wetter the more it dries?","A towel."],["What has hands but cannot clap?","A clock."],["What comes once in a minute, twice in a moment, but never in a thousand years?","The letter M."],["What has a neck but no head?","A bottle."],["What can you catch but not throw?","A cold."],["The more of me there is, the less you see. What am I?","Darkness."],["What goes up but never comes down?","Your age."]];
var RV=[{w:0,q:"Who has been writing these letters?",o:["A forger copying Marlowe","Marlowe herself","A rival mapmaker"],a:1,t:"The letters are Marlowe's. She stamped every one herself, and she is not missing: she is leading you. Your first job was to notice, and you already have."},{w:2,q:"What is the grey seal?",o:["A calling card for whoever is rewriting the letters","A decorative postal mark","Marlowe's code for danger"],a:0,t:"Someone has been rewriting the letters. Lines that said 'be gentler with yourself' now say 'try harder to fit in'. The tamperer leaves a grey seal and calls itself the Hush."},{w:3,q:"Why is the Hush rewriting the letters?",o:["He wants fame","He is afraid for people like himself","He works for the post office"],a:1,t:"The Hush is a person: Aldous Vane, Marlowe's old research partner. He believes quiet sameness is kindness because masking nearly broke him. He is not trying to hurt anyone. He is trying to spare them."},{w:6,q:"What is the route really for?",o:["Winning against Vane","Reaching Vane with understanding","Selling maps"],a:1,t:"Marlowe built the route to reach Vane, not to defeat him. Every stamp is an invitation, and every field assignment is a small act of love sent into the world."},{w:4,q:"What relights a Signal Tower?",o:["Money","Someone sharing what they wish others understood","Perfect behaviour"],a:1,t:"The Signal Towers are real: places where people say what they wish others understood. Each awareness act you do relights one, and the Hush's grey seals fade a little more."},{w:0,q:"Who were the letters written for?",o:["Vane","You, the traveller","The Hush"],a:1,t:"Marlowe's last log reads: 'I did not vanish. I stepped back so the route could be yours. The letters were never only for Vane. They were for whoever needed them most.'"},{w:5,q:"How does the story end?",o:["Vane is defeated","Vane drops the mask and writes his own letter","The letters are burned"],a:1,t:"In London, Vane writes a letter of his own, unmasked and unedited. The route ends where acceptance begins: first for him, then for you, then for everyone you reach. Keep sending the signal."}];
var GAG=[["P.S. Cartographers never get lost. We just discover new places without permission.","P.S. If this note smells of peppermint, I was nervous. If not, I ran out of peppermint.","P.S. I drew this route in three colours. Two of them are for feelings.","P.S. Please do not fold along the dotted line. The dotted line is load-bearing."],["Tomas checks his watch. 'I am exactly on time for a different day.'","Tomas is carrying nine parcels and has lost track of which one is a sandwich.","'Never late, never early,' Tomas says. 'Only dramatically timed.'","Tomas salutes with a baguette he insists is official post."],["Priya calls this node Biscuit. 'Every good tower has a snack name. It is science.'","Priya taps a dial. 'Signal is strong, which is rude, because I wanted an excuse to buy more cable.'","'Do not touch the red wire,' Priya says. 'Or the blue one. Or my sandwich.'","Priya labels everything. Even the silence has a label: 'Do not interrupt.'"],["Kofi has filed this clue under 'Mysterious, see also Suspicious, see also Lunch'.","'I alphabetise my feelings,' Kofi says. 'Today is a solid B for Bewildered.'","Kofi sniffs the paper. 'Eighteenth century ink, twenty-first century gravy.'","Kofi stamps the page twice, 'once for the archive, once for morale'."],["Yuki is deep in conversation with a gull. The gull appears to be winning.","'The lighthouse has opinions,' Yuki says. 'Mostly about my tea.'","Yuki writes tonight's weather in her log: 'Moody, with a chance of metaphors.'","A gull steals the envelope. Yuki gets it back, with an apology and a chip."],["A grey note is pinned nearby: 'Please be quieter.' It is signed with a very small, very tidy flourish.","Someone has alphabetised the pigeons. Vane's work, clearly. Or Kofi's.","The seal on this one reads 'The Hsuh'. Even the Hush makes typos.","A grey umbrella has been left on the bench. It is not raining. It is a statement."],["Lucía hands you a flask. 'Soup first. Mysteries are better on a warm stomach.'","'I solved three cases with paprika,' Lucía says, 'and one with a very firm hug.'","Lucía taste-tests the evidence and declares it 'needs salt, and honesty'.","Lucía insists the clue is a recipe. It may also be a recipe."],["Sef plays a tune about the clue. It rhymes 'envelope' with 'telescope' and gets away with it.","'I wrote you a song,' Sef says. 'It is mostly kazoo.'","Sef taps a rhythm on the table. It is either a code or a snack order.","Sef bows to a pigeon, which has done nothing to deserve it."]];
OPN.push("The map says {s} is a quiet little place. The map is lying, politely.","A very small child at {s} announces that you are late, then hands you a very important leaflet.","There is a lamp in {s} that was lit an hour before you arrived. Nobody will say who lit it.","{w} is already at {s}, pretending not to have been waiting.","The stamp at {s} lands with a thud that echoes in a way stamps should not.","Someone has chalked an arrow on the pavement in {s}. It points at you.","{w} arrives in {s} out of breath, holding a map upside down on purpose.","In {s}, the postbox is warm. Warm postboxes are a clue. Or it is a sunny day.");
HK.push("A line has been crossed out so hard the paper tore. What did it say?","The postmark is dated tomorrow. {w} says it is a printing error and goes pink.","Someone has underlined the word 'listen' three times and drawn a tiny ear.","The back says: 'Not everything that is quiet is empty.'","A grey thumbprint sits in the corner, neat as a signature.","'Does this seem too convenient?' {w} whispers. It does.","There is a drawing of a door with no wall around it. Marlowe never drew by accident.","'Remember this one,' says {w}. 'It will matter later. Or it will not. That is the fun.'");
var THR=[["The Grey Seal",[3,"The grey seal is always pressed slightly crooked. Whoever is forging it is left-handed, or in a hurry, or both."],[12,"The seal's ink is soot mixed with printer toner. Someone has a very tidy workshop and a very guilty conscience."],[30,"Held up to a lamp, the seal shows tiny initials: A.V. Not a forgery. A confession."]],["Marlowe's Compass",[3,"Marlowe's compass points to people, not north. Tomas insists it points to snacks."],[12,"Every stop where the needle trembled is a place where someone felt understood for the first time."],[30,"The needle has been quietly pointing at you since the first stamp."]],["Page Thirteen",[3,"Page thirteen is missing from every copy of Marlowe's atlas. Superstition, or sabotage?"],[12,"Page thirteen was not stolen. It was folded into a letter and sent somewhere clever."],[30,"Page thirteen reads: 'You are not behind. You are on a different route.'"]],["The Pigeon",[3,"A pigeon keeps turning up. It is almost certainly just a pigeon."],[12,"The pigeon wears a tiny brass tag: 'Return to Dr M. Not for sale. Not for soup.'"],[30,"The pigeon is Marlowe's. It has been carrying her letters all along, which explains Tomas being late."]]];
var FN=["(Footnote: the mysterious man in the grey coat was a man in a grey coat. He has been apologised to.)","(Footnote: the pigeon is still not a spy. Probably.)","(Footnote: the spice cupboard was not a secret entrance. Lucía has asked everyone to stop checking.)","(Footnote: the loud humming was a fridge. A very dedicated fridge.)","(Footnote: the ghost lighthouse was a lighthouse. Yuki is disappointed and relieved.)","(Footnote: the message in the bottle read 'help, I am a bottle'. It was a very short mystery.)","(Footnote: no pigeons were harmed in the making of this ending. One got a medal.)"],CLF=["But one line in the letter is in someone else's handwriting. Whose?","The grey seal has a signature. It is smudged, but the first letter is A.","Vane left one last note: 'Come to the towers. I have something to admit.'","In the margin of the route is a tiny sketch: eight towers, all unlit.","Marlowe's last log entry stops mid-sentence. Why?","There is a train waiting in the Americas. Nobody ordered it.","The letter is signed with a small drawing of a pigeon. Of course it is."];
function thrCount(t){var n=0,j;for(j=0;j<STOPS.length;j++)if(CUM[j]<=S.km&&j%4===t)n++;return n}
function caseBoard(){return'<h2>Case board</h2>'+THR.map(function(t,i){var n=thrCount(i),un=t.slice(1).filter(function(x){return n>=x[0]}),nx=t.slice(1).filter(function(x){return n<x[0]})[0];return'<div class="vgoal" style="--c:var(--gem);margin-bottom:10px"><b>'+t[0]+', '+n+' clues</b>'+un.map(function(x){return x[1]}).join(" ")+(nx?'<br><i>Next note at '+nx[0]+' clues.</i>':'')+'</div>'}).join("")}
function legOf(j){for(var l=0;l<LS.length;l++)if(j>=LS[l]&&j<=LE[l])return l;return LS.length-1}
function story(j){var bt=beatOf(j);if(bt)return{w:bt[0],thr:j%4,beat:1,text:bt[0]===0?'<span class="hand">'+bt[1]+'</span>':bt[1]};var l=Math.min(legOf(j),6),q=STOPS[j],a=j*31+7,sp=SPK[l],w=(l===6&&j>=LE[6]-4)?5:sp[j%sp.length],t=OPN[a%OPN.length]+" "+EVD[(a*3)%8].replace("{m}",MOT[l][(a>>1)%6])+" "+HK[(a*5+3)%HK.length];if(a%5<2){var gg=GAG[w][(a>>2)%4];t+=" "+(w===0?'<span class="hand">'+gg+"</span>":gg)}return{w:w,thr:j%4,text:t.split("{s}").join(q.n).split("{w}").join(CH[w][0].split(" ")[0])}}
function ctry(c){try{return new Intl.DisplayNames(["en"],{type:"region"}).of(c)}catch(e){return c}}
function assign(q){var j=STOPS.indexOf(q),cn=ctry(q.c),t=j%6,R=RID[j%12];return[{t:"Taste",txt:"Cook, order or buy a dish from "+cn+". Write what it was, and rate it out of ten."},{t:"Words",txt:"Learn to say hello and thank you in a language of "+cn+". A dramatic accent is optional."},{t:"Facts",txt:"Find three facts about "+q.n+" and write your favourite. Ridiculous facts score double."},{t:"Riddle",txt:"Solve this riddle: "+R[0],ans:R[1]},{t:"Sound",txt:"Listen to music from "+cn+" for one task or one walk. Note a favourite."},{t:"Kindness",txt:"Share one thing you wish more people understood about AuDHD with someone, or leave a kind note for someone who may feel unseen."}][t]}
function bonusPct(){var r=0;HOB.forEach(function(a){r+=rk(a.id)});return Math.min(40,r*.5+(S.reveals||0)+Math.min(10,Math.floor((S.insight||0)/4)))}
function KB(m){return Math.round(K(m)*(1+bonusPct()/100))}
function locOf(km){var i=where(km),a=STOPS[i],b=STOPS[i+1],A=XY[a.n]||[0,0],fr=b&&a.d?Math.min(1,(km-CUM[i])/a.d):0;if(!b||!XY[b.n])return A;var B=XY[b.n],dl=B[1]-A[1];if(dl>180)dl-=360;if(dl<-180)dl+=360;return[A[0]+(B[0]-A[0])*fr,A[1]+dl*fr]}
function theory(l,q){var T=RV[l];ov("theory","Your theory",'<div class="pg"><small>Leg '+(l+1)+' theory</small><h3>'+T.q+'</h3>'+T.o.map(function(o,k){return'<button class="btn" data-i="'+k+'">'+o+'</button>'}).join("")+'</div>',function(i,el){el.close();reveal(l,+i,q)})}
function reveal(l,pick,q){var T=RV[l],ok=pick===T.a;S.theory=S.theory||{};if(!S.theory[l]){S.theory[l]={pick:pick,ok:ok};S.reveals=(S.reveals||0)+1}sfx("chime");setTimeout(function(){sfx("thud")},Math.min(9000,((ok?4:5)+T.t.split(" ").length+FN[l].split(" ").length+CLF[l].split(" ").length)*40));ov("reveal","The reveal",'<div class="pc"><div class="pc-top">'+face(T.w)+'<div><b>'+esc(CH[T.w][0])+'</b><small>'+esc(CH[T.w][1])+'</small></div></div><small>Big reveal, leg '+(l+1)+'</small><p class="clue">'+tw((ok?"You read it right. ":"Not quite, but close. ")+T.t,0)+'<i>'+tw(FN[l],((ok?4:5)+T.t.split(" ").length)*.04)+'</i>'+tw(CLF[l],((ok?4:5)+T.t.split(" ").length+FN[l].split(" ").length)*.04)+'</p><p class="sig">New bonus: +1% distance for every reveal.</p><button class="btn" data-i="ok">Continue</button></div>',function(i,el){el.close();postcard(q)})}
function showPrologue(){var P=[[0,"You do not know me yet. I draw maps of minds, and yours was on my list. If you are reading this, you hold a stamp and a loop of the world lies ahead."],[1,"Every stop holds a clue and a small job. Cook a dish, learn a word, share something kind, and please do not feed the pigeon. Spread love and awareness of AuDHD as you go."],[2,"Something called the Hush is rewriting our letters. Collect clues, make a theory at the end of each leg, and light the Signal Towers. Go at your own pace."]],k=0;function h(){return'<div class="pc"><div class="pc-top">'+face(P[k][0])+'<div><b>'+esc(CH[P[k][0]][0])+'</b><small>'+esc(CH[P[k][0]][1])+'</small></div></div><p class="clue">'+P[k][1]+'</p><button class="btn" data-i="n">'+(k<2?"Next":"Begin the journey")+'</button></div>'}ov("prologue","The story begins",h(),function(i,el){if(k<2){k++;el.innerHTML=h();el.querySelector(".btn").focus()}else{S.prologueDone=true;save();el.close();setTimeout(chk,300)}})}
function vCase(){var o='<h2>Clue files</h2><p class="sub">Insight '+(S.insight||0)+'. Distance bonus +'+bonusPct().toFixed(1)+'%.</p>',cl=legOf(where(S.km));LEGS.forEach(function(g,l){var rs=[],j;for(j=LS[l];j<=LE[l];j++)if(CUM[j]<=S.km)rs.push(j);if(!rs.length)return;o+='<h2>'+esc(g[0].replace(/^Leg \d+: /,""))+'</h2>'+((S.theory||{})[l]?'<div class="vgoal" style="--c:var(--gem)"><b>Reveal</b>'+RV[l].t+'</div>':"")+'<details class="more"'+(l===cl?" open":"")+'><summary>'+rs.length+' clues</summary>'+rs.reverse().map(function(j){return'<p class="clue"><b>'+esc(STOPS[j].n)+'.</b>'+(story(j).beat?' <b>Chapter beat.</b> ':' ')+story(j).text+'</p>'}).join("")+'</details>'});return o+(o.indexOf("<details")<0?empty("env","Your first clue arrives with your first stamp."):"")}
var CP=[1,2,3,6,4,7,0,5],CT=["No rush. Start with the smallest task when you are ready.","That counts. Every stamp starts with one step.","Full set. I will keep the lantern lit."],CF=["Different minds, same sky.","I will carry the post.","Signal is strong today.","I will log it in the archive.","The light is on.","I am learning too.","There is soup when you are done.","I will play you onward."];
var DT=["Pen-pal postcard: write two kind lines to someone you have not spoken to lately.","Storm warning: do your first task before midday.","Border queue: take five slow breaths before your next task.","Market stall: tidy one small surface for five minutes.","Lost luggage: find one misplaced thing and give it a home.","Street musician: listen to one song from start to finish.","Night train: put your phone away 30 minutes before bed.","Local guide: ask someone about their favourite place.","Language lesson: learn one new word in any language.","Lighthouse: step outside for two minutes of daylight.","Picnic: eat one meal somewhere different, even a different chair.","Postcard home: send a short message to someone who matters to you."];
var CHP=[[2,"Neurodiversity Celebration Week","Share one strength of a neurodivergent person you admire."],[3,"Autism Acceptance Month","Tell someone one thing acceptance looks like to you."],[9,"ADHD Awareness Month","Share one thing that helps you with someone who might need to hear it."],[11,"Winter Lanterns","Do one kind thing for someone, quietly."]],MN=["January","February","March","April","May","June","July","August","September","October","November","December"];
var TW=[[51.5,-0.1],[64.1,-21.9],[41.7,44.8],[30,31.2],[6.9,79.9],[35.7,139.7],[-13.8,-171.8],[-34.6,-58.4]];
function unl(){return Math.min(8,1+(S.reveals||0))}
function curComp(){return CP[S.comp!=null&&S.comp<unl()?S.comp:0]}
function chapNow(){var d=new Date(),c=CHP.filter(function(x){return x[0]===d.getMonth()})[0];return c?{n:c[1],t:c[2],k:c[1]+d.getFullYear()}:null}
function nextChap(){var m=new Date().getMonth(),b=CHP.slice().sort(function(a,c){return((a[0]-m+12)%12)-((c[0]-m+12)%12)})[0];return b[1]+" in "+MN[b[0]]}
function detourOf(){var k=today(),h=0,i;for(i=0;i<k.length;i++)h=(h*31+k.charCodeAt(i))%9973;return h%4===0?DT[h%DT.length]:null}
function souv(j){return MOT[Math.min(legOf(j),6)][((j*31+7)>>1)%6]+", from "+STOPS[j].n}
function kindCount(){return Object.keys(S.fa).filter(function(k){var j=-1,i;for(i=0;i<STOPS.length;i++)if(STOPS[i].n===k){j=i;break}return j>=0&&j%6===5}).length}
