 for(var i=0;i<offset;i++)cal+='<div></div>';
 for(var d=1;d<=days;d++){
  var ds=y+"-"+pad(m+1)+"-"+pad(d),hd=S.hist[ds],isT=ds===today(),isS=ds===selDay;
  var tag="",cs="";if(hd&&hd.km)cs=' style="background:color-mix(in srgb,var(--'+(hd.tier||"green")+') '+Math.min(55,Math.round(hd.km/5)+8)+'%,var(--bg))"';
  if(hd){if(hd.hmin>=60)tag="&#9733; "+Math.round(hd.km)+"k";else if(hd.km||hd.hmin)tag=Math.round(hd.km)+"k"}
  cal+='<button class="cal-day'+(isT?' today':'')+(isS?' sel':'')+'" data-a="selday" data-id="'+ds+'"'+cs+'><span>'+d+'</span><span class="cal-tag">'+tag+'</span></button>';
 }
